+      function swirl(cloud, origin, radius, ySpan, speed, inward) {
+        const pos = cloud.pos;
+        cloud.t += dt * speed;
+        for (let i = 0; i < cloud.n; i++) {
+          const s = cloud.seed[i];
+          const a = cloud.t * (0.6 + s) + s * 6.28;
+          const r = radius * (0.25 + (s * 0.75));
+          const y = origin.y + Math.sin(cloud.t * 0.7 + s * 8) * ySpan;
