+      moonL.shadow.camera.right = 6;
+      moonL.shadow.camera.top = 6;
+      moonL.shadow.camera.bottom = -6;
+      moonL.shadow.bias = -0.00025;
+      scene.add(moonL);
+      const rim = new THREE.DirectionalLight(0xffc090, 0.45);
+      rim.position.set(-5, 3, 2);
+      scene.add(rim);
+      const fill = new THREE.PointLight(0x7eb0ff, 4, 8, 2);
+      fill.position.set(2.4, 2.2, 2.8);
+      scene.add(fill);
+
+      const sky = new THREE.Mesh(
+        new THREE.SphereGeometry(16, 32, 16),
+        new THREE.ShaderMaterial({
+          side: THREE.BackSide,
+          uniforms: {},
+          vertexShader: `varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
+          fragmentShader: `varying vec3 vP; void main(){
