+      buildInterior(scene, mats);
+      buildExterior(scene, mats);
+      buildWall(scene, mats);
+      splitGroup = buildSplit();
+      monoGroup = buildMono();
+      scene.add(splitGroup, monoGroup);
+      addDrips(scene);
+
+      particles = makeParticles();
+      scene.add(particles.room.pts, particles.outdoor.pts, particles.ref.pts, particles.heat.pts);
+
+      clock = new THREE.Clock();
+      bindUI();
+      setSystem("split");
+      setMode("cooling");
+      setPlaying(!reduced);
+      if (reduced) document.getElementById("btn-play").textContent = "Play";
+
+      window.addEventListener("resize", onResize);
+      renderer.domElement.addEventListener("webglcontextlost", (e) => {
+        e.preventDefault();
