+      renderer.setSize(w, h);
+      labelRenderer.setSize(w, h);
+      renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
+    }
+
+    function tick() {
+      const dt = Math.min(0.05, clock.getDelta());
+      controls.update();
+      if (S.playing) {
+        for (const f of anim.fans) {
+          if (S.system === "split" && f.mesh.parent && splitGroup.visible === false) continue;
+          f.mesh.rotation[f.axis] += dt * f.speed;
+        }
+        for (const gl of anim.glow) {
+          gl.material.emissiveIntensity = 1.1 + Math.sin(clock.elapsedTime * 6) * 0.4;
+        }
+        updateParticles(dt);
+        updateDrips(dt);
+      }
+      if (S.tour) {
+        S.tourAcc += dt;
+        if (S.tourAcc > 6.5) {
+          S.tourAcc = 0;
+          const n = (S.tourIndex + 1) % TOUR.length;
+          showTourStep(n);
+        }
+      }
+      renderer.render(scene, camera);
+      labelRenderer.render(scene, camera);
+    }
+
+    init();
+  </script>
+</body>
+</html>

