  "--headless=new",
  `--remote-debugging-port=${PORT}`,
  "--disable-gpu",
  "--no-first-run",
  "--no-default-browser-check",
  "--use-gl=angle",
  "--use-angle=swiftshader",
  "--enable-webgl",
  "--ignore-gpu-blocklist",
  "--window-size=1400,900",
  "about:blank",
], { stdio: ["ignore", "pipe", "pipe"] });

let stderr = "";
chrome.stderr.on("data", (d) => { stderr += d.toString(); });

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

async function waitPort() {
  for (let i = 0; i < 40; i++) {
    try {
      const r = await fetch(`http://127.0.0.1:${PORT}/json/version`);
      if (r.ok) return r.json();
    } catch {}
    await sleep(150);
  }
  throw new Error("CDP not ready\n" + stderr.slice(-500));
}

async function cdp(ws, method, params = {}, sessionId) {
  const id = cdp._id = (cdp._id || 0) + 1;
  const msg = { id, method, params };
  if (sessionId) msg.sessionId = sessionId;
  ws.send(JSON.stringify(msg));
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error("timeout " + method)), 12000);
    const on = (ev) => {
      const data = JSON.parse(ev.data);
      if (data.id === id) {
        clearTimeout(t);
        ws.removeEventListener("message", on);
        if (data.error) reject(new Error(method + " " + JSON.stringify(data.error)));
        else resolve(data.result);
      }
    };
    ws.addEventListener("message", on);
  });
}

const logs = [];
try {
  const ver = await waitPort();
  const ws = new WebSocket(ver.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.addEventListener("open", res); ws.addEventListener("error", rej); });

  const { targetId } = await cdp(ws, "Target.createTarget", { url: "about:blank" });
  const { sessionId } = await cdp(ws, "Target.attachToTarget", { targetId, flatten: true });
  const send = (m, p) => cdp(ws, m, p, sessionId);

  ws.addEventListener("message", (ev) => {
    const data = JSON.parse(ev.data);
