      const txt = (data.params.args || []).map((a) => a.value ?? a.description ?? a.type).join(" ");
      logs.push(["console", data.params.type, txt]);
    }
    if (data.method === "Runtime.exceptionThrown") {
      logs.push(["exception", data.params.exceptionDetails?.text, data.params.exceptionDetails?.exception?.description]);
    }
  });

  await send("Runtime.enable");
  await send("Page.enable");
  await send("Page.navigate", { url: URL });
  await send("Page.loadEventFired").catch(() => {});
  await sleep(2500);

  const evalp = async (expr) => {
    const r = await send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
    return r.result.value;
  };

  const info = await evalp(`({
    title: document.title,
    h1: document.querySelector('h1')?.textContent,
    fail: document.getElementById('fail')?.classList.contains('show'),
